<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Bouncing Ball Playground</title>
  <style>
    * { box-sizing: border-box; }

    body {
      min-height: 100vh;
      margin: 0;
      display: grid;
      place-items: center;
      padding: 24px;
      color: #eef2ff;
      background:
        radial-gradient(circle at 50% 20%, #20294a 0, #101526 40%, #080b13 100%);
      font-family: system-ui, sans-serif;
    }

    main {
      width: min(92vw, 660px);
      text-align: center;
    }

    h1 {
      margin: 0 0 16px;
      font-size: clamp(1.35rem, 4vw, 2rem);
      letter-spacing: .03em;
    }

    #sim {
      display: block;
      width: 600px;
      height: 520px;
      max-width: 100%;
      min-height: 400px;
      margin: auto;
      cursor: crosshair;
      border: 1px solid #445078;
      border-radius: 18px;
      background: #0c1120;
      box-shadow:
        0 24px 70px #0009,
        inset 0 0 50px #18203d80;
      touch-action: none;
    }

    .controls {
      display: flex;
      justify-content: center;
      flex-wrap: wrap;
      gap: 10px;
      margin-top: 16px;
    }

    button {
      min-width: 110px;
      padding: 11px 18px;
      border: 1px solid #55628d;
      border-radius: 999px;
      color: #f7f8ff;
      background: linear-gradient(#303b68, #222b50);
      font: 700 0.95rem system-ui, sans-serif;
      cursor: pointer;
      box-shadow: 0 5px 15px #0006;
      transition: transform .12s, filter .12s;
    }

    button:hover { filter: brightness(1.18); }
    button:active { transform: translateY(2px) scale(.97); }
  </style>
</head>
<body>
  <main>
    <h1>Bouncing Ball Playground</h1>
    <canvas id="sim" width="600" height="520" aria-label="Bouncing ball simulation"></canvas>
    <div class="controls">
      <button id="drop" type="button">Drop Ball</button>
      <button id="play" type="button">Pause</button>
      <button id="clear" type="button">Clear</button>
    </div>
  </main>

  <script>
    (() => {
      "use strict";

      const canvas = document.getElementById("sim");
      const ctx = canvas.getContext("2d");
      const dropButton = document.getElementById("drop");
      const playButton = document.getElementById("play");
      const clearButton = document.getElementById("clear");

      const W = canvas.width;
      const H = canvas.height;
      const gravity = 0.42;
      const restitution = 0.82;
      const state = [];
      let running = true;
      let lastTime = performance.now();
      let hue = 185;

      function finite(value, fallback) {
        value = Number(value);
        return Number.isFinite(value) ? value : fallback;
      }

      function draw() {
        ctx.clearRect(0, 0, W, H);

        const background = ctx.createLinearGradient(0, 0, 0, H);
        background.addColorStop(0, "#11182d");
        background.addColorStop(1, "#090d18");
        ctx.fillStyle = background;
        ctx.fillRect(0, 0, W, H);

        ctx.strokeStyle = "#7986b51c";
        ctx.lineWidth = 1;
        for (let x = 30; x < W; x += 30) {
          ctx.beginPath();
          ctx.moveTo(x, 0);
          ctx.lineTo(x, H);
          ctx.stroke();
        }
        for (let y = 30; y < H; y += 30) {
          ctx.beginPath();
          ctx.moveTo(0, y);
          ctx.lineTo(W, y);
          ctx.stroke();
        }

        for (const ball of state) {
          ctx.save();
          ctx.shadowColor = `hsla(${ball.hue}, 95%, 65%, .65)`;
          ctx.shadowBlur = 16;

          const shine = ctx.createRadialGradient(
            ball.x - ball.r * .32,
            ball.y - ball.r * .38,
            ball.r * .08,
            ball.x,
            ball.y,
            ball.r
          );
          shine.addColorStop(0, "#ffffff");
          shine.addColorStop(.16, `hsl(${ball.hue}, 95%, 75%)`);
          shine.addColorStop(.65, `hsl(${ball.hue}, 82%, 55%)`);
          shine.addColorStop(1, `hsl(${ball.hue}, 78%, 30%)`);

          ctx.beginPath();
          ctx.arc(ball.x, ball.y, ball.r, 0, Math.PI * 2);
          ctx.fillStyle = shine;
          ctx.fill();
          ctx.restore();
        }
      }

      function addBall(x, y, vx = 0, vy = 0, r) {
        const radius = Math.max(4, Math.min(
          finite(r, 12 + Math.random() * 10),
          Math.min(W, H) / 2
        ));

        const ball = {
          x: Math.max(radius, Math.min(W - radius, finite(x, W / 2))),
          y: Math.max(radius, Math.min(H - radius, finite(y, radius))),
          vx: finite(vx, 0),
          vy: finite(vy, 0),
          r: radius,
          hue: hue = (hue + 47 + Math.random() * 30) % 360
        };

        state.push(ball);
        draw();
        return ball;
      }

      function advanceSubstep(ball, dt) {
        ball.vy += gravity * dt;
        ball.x += ball.vx * dt;
        ball.y += ball.vy * dt;

        const left = ball.r;
        const right = W - ball.r;
        const top = ball.r;
        const bottom = H - ball.r;

        while (ball.x < left || ball.x > right) {
          if (ball.x < left) {
            ball.x = left + (left - ball.x);
            ball.vx = Math.abs(ball.vx) * restitution;
          } else {
            ball.x = right - (ball.x - right);
            ball.vx = -Math.abs(ball.vx) * restitution;
          }
        }

        while (ball.y < top || ball.y > bottom) {
          if (ball.y < top) {
            ball.y = top + (top - ball.y);
            ball.vy = Math.abs(ball.vy) * restitution;
          } else {
            ball.y = bottom - (ball.y - bottom);
            ball.vy = -Math.abs(ball.vy) * restitution;
          }
        }

        ball.x = Math.max(left, Math.min(right, ball.x));
        ball.y = Math.max(top, Math.min(bottom, ball.y));
      }

      function step(dt = 1) {
        dt = finite(dt, 1);
        if (dt < 0) dt = 0;

        const parts = Math.max(1, Math.ceil(dt / 0.5));
        const slice = dt / parts;

        for (let i = 0; i < parts; i++) {
          for (const ball of state) advanceSubstep(ball, slice);
        }

        draw();
      }

      function clear() {
        state.length = 0;
        draw();
      }

      window.sim = {
        w: W,
        h: H,
        balls() {
          return state.map(({ x, y, vx, vy, r }) => ({ x, y, vx, vy, r }));
        },
        addBall,
        clear,
        step
      };

      canvas.addEventListener("pointerdown", event => {
        const rect = canvas.getBoundingClientRect();
        const x = (event.clientX - rect.left) * W / rect.width;
        const y = (event.clientY - rect.top) * H / rect.height;
        addBall(x, y, (Math.random() - .5) * 5, (Math.random() - .5) * 3);
      });

      dropButton.addEventListener("click", () => {
        const r = 12 + Math.random() * 10;
        addBall(
          r + Math.random() * (W - r * 2),
          r + 3,
          (Math.random() - .5) * 5,
          Math.random()
        );
      });

      playButton.addEventListener("click", () => {
        running = !running;
        playButton.textContent = running ? "Pause" : "Play";
        lastTime = performance.now();
      });

      clearButton.addEventListener("click", clear);

      function animate(now) {
        if (running) {
          const dt = Math.min(3, Math.max(0, (now - lastTime) / (1000 / 60)));
          step(dt);
        }
        lastTime = now;
        requestAnimationFrame(animate);
      }

      addBall(W * .42, 90, 2.7, -1);
      addBall(W * .58, 160, -2.1, -3, 17);
      requestAnimationFrame(animate);
    })();
  </script>
</body>
</html>
